### C++

```cpp
#include <bits/stdc++.h>
using namespace std;
using u64 = unsigned long long;

// 试除分解：只返回各质因子的幂次
static vector<int> factor_exps(u64 n) {
	vector<int> exps;
	if (n % 2 == 0) {
		int c = 0;
		while (n % 2 == 0) { n /= 2; ++c; }
		exps.push_back(c);
	}
	for (u64 p = 3; p <= n / p; p += 2) {
		if (n % p == 0) {
			int c = 0;
			while (n % p == 0) { n /= p; ++c; }
			exps.push_back(c);
		}
	}
	if (n > 1) exps.push_back(1);
	return exps;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int T;
	if (!(cin >> T)) return 0;
	while (T--) {
		u64 x; cin >> x;
		if (x == 1) { cout << 0 << '\n'; continue; } // 若题面保证 x>=2，可删除
		vector<int> exps = factor_exps(x);

		// 计算 tau(x) = ∏(a_i+1)
		u64 tau = 1;
		for (int a : exps) tau *= (u64)(a + 1);

		// 计算分层和 ∑ 2^{r_ell}
		int A = 0;
		for (int a : exps) A = max(A, a);
		u64 layerSum = 0;
		for (int ell = 1; ell <= A; ++ell) {
			int r = 0;
			for (int a : exps) if (a >= ell) ++r;
			layerSum += (1ULL << r);
		}

		cout << max(tau, layerSum) << '\n';
	}
	return 0;
}
```

