		if n % p == 0:
			c = 0
			while n % p == 0:
				n //= p
				c += 1
			exps.append(c)
		p += 2
	if n > 1:
		exps.append(1)
	return exps

def solve():
	data = sys.stdin.read().strip().split()
	if not data: return
	it = iter(data)
	T = int(next(it))
	for _ in range(T):
		x = int(next(it))
		if x == 1:
			print(0)
			continue
		exps = factor_exps(x)

		# tau(x)
