import sys

def factor_exps(n: int):
    """返回正整数n的所有质因子的指数列表"""
    exps = []
    # 处理质数2
    if n % 2 == 0:
        c = 0
        while n % 2 == 0:
            n //= 2
            c += 1
        exps.append(c)
    # 处理奇数质数
    p = 3
    while p * p <= n:
        if n % p == 0:
            c = 0
            while n % p == 0:
                n //= p
                c += 1
            exps.append(c)
        p += 2
    if n > 1:
        exps.append(1)
    return exps

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out = []
    for _ in range(T):
        x = int(next(it))
        exps = factor_exps(x)
        # 计算 c(x) = ∏(e_i + 1)
        tau = 1
        for e in exps:
            tau *= (e + 1)
        # 按层计算总和 ∑ 2^{r_ell}
        A = max(exps) if exps else 0
        layer_sum = 0
        for ell in range(1, A + 1):
            r = sum(1 for e in exps if e >= ell)
            layer_sum += (1 << r)
        out.append(str(max(tau, layer_sum)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
```

