import sys

def factor_exps(n):
    exps = []
    if n % 2 == 0:
        c = 0
        while n % 2 == 0:
            n //= 2
            c += 1
        exps.append(c)
    p = 3
    while p * p <= n:
        if n % p == 0:
            c = 0
            while n % p == 0:
                n //= p
                c += 1
            exps.append(c)
        p += 2
    if n > 1:
        exps.append(1)
    return exps

def solve():
    data = sys.stdin.read().split()
    if not data: return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        x = int(next(it))
        exps = factor_exps(x)
        tau = 1
        for e in exps:
            tau *= (e + 1)
        A = max(exps) if exps else 0
        layer_sum = 0
        for l in range(1, A + 1):
            r = sum(1 for e in exps if e >= l)
            layer_sum += (1 << r)
        out_lines.append(str(max(tau, layer_sum)))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

