import java.io.*;
import java.util.*;

public class Main {
    static List<Integer> factorExps(long n) {
        List<Integer> exps = new ArrayList<>();
        if (n % 2 == 0) {
            int c = 0;
            while (n % 2 == 0) {
                n /= 2;
                c++;
            }
            exps.add(c);
        }
        for (long p = 3; p <= n / p; p += 2) {
            if (n % p == 0) {
                int c = 0;
                while (n % p == 0) {
                    n /= p;
                    c++;
                }
                exps.add(c);
            }
        }
        if (n > 1) exps.add(1);
        return exps;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        while (T-- > 0) {
            long x = Long.parseLong(br.readLine().trim());
            List<Integer> exps = factorExps(x);
            long tau = 1;
            for (int e : exps) tau *= (e + 1L);
            int A = 0;
            for (int e : exps) A = Math.max(A, e);
            long layerSum = 0;
            for (int ell = 1; ell <= A; ell++) {
                int r = 0;
                for (int e : exps) if (e >= ell) r++;
                layerSum += (1L << r);
            }
            sb.append(Math.max(tau, layerSum)).append('\n');
        }
        System.out.print(sb);
    }
}
